import t,{getImageUrl as e,safeFetchJson as a}from"./config.min.js";const n=document.getElementById("seo-product-table");function s(t=""){const e=document.createElement("div");return e.textContent=t,e.innerHTML}document.addEventListener("DOMContentLoaded",async function(){try{const o=await a(`${t}/api/product/all`);if(!o.length)return void(n.innerHTML='<tr><td colspan="5" class="px-6 py-10 text-center text-gray-400">No products found.</td></tr>');n.innerHTML=o.map(t=>`\n            <tr class="hover:bg-gray-50/70">\n                <td class="px-6 py-4"><div class="flex items-center gap-3"><img class="h-12 w-12 rounded-lg object-cover border" src="${e(t.imagepath,"./static/alora image 2.jpeg")}" alt="" onerror="this.src='./static/alora image 2.jpeg'"><span class="font-bold text-gray-800">${s(t.name)}</span></div></td>\n                <td class="px-6 py-4 text-gray-600 max-w-xs"><p class="line-clamp-2">${s(t.description||"")}</p></td>\n                <td class="px-6 py-4"><span class="text-amber-600 font-bold"><i class="fa-solid fa-star"></i> ${t.rating??4.5}</span></td>\n                <td class="px-6 py-4 text-gray-600">${(t.variants||[]).map(t=>s(t.volume)).join(", ")||"—"}</td>\n                <td class="px-6 py-4 text-right"><a class="inline-flex items-center gap-1.5 bg-indigo-50 border border-indigo-200 text-indigo-700 hover:bg-indigo-100 px-3 py-1.5 rounded-lg text-xs font-bold" href="./seoproductupdate.html?id=${t._id}"><i class="fa-solid fa-pen-to-square"></i> Edit allowed fields</a></td>\n            </tr>`).join("")}catch(t){n.innerHTML=`<tr><td colspan="5" class="px-6 py-10 text-center text-red-600">Could not load products: ${s(t.message)}</td></tr>`}});